def kn(key):
    return lambda lang: key_name(key, lang)


def ask_key_of(text, key, others, music=None):
    return ask(text, [kn(key)] + [kn(k) for k in others], music=music)


def piano(rh, lh, key='C', meter='none', labels=None, unit='1/4'):
    """Two staves: right-hand chords (lists of pitches) over bass notes; labels under the bass."""
    upper = ' '.join(chord_abc(c, '2', key) for c in rh)
    lower = ' '.join((f'"_{labels[i]}"' if labels else '') + abc_pitch(p, key) + '2' for i, p in enumerate(lh))
    return (f'X:1\n%%stretchlast 1\n%%annotationfont Inter 14\n%%staves {{RH LH}}\nM:{meter}\nL:{unit}\nK:{key}\n'
            f'V:RH clef=treble\nV:LH clef=bass\n[V:RH] {upper} |]\n[V:LH] {lower} |]\n')


