CADENCES = [
  ('perfect', L('Perfect (authentic) cadence: V - I', 'Ganzschluss (authentische Kadenz): V – I', 'Cadence parfaite : V – I'),
   [['F4', 'A4', 'C5'], ['D4', 'G4', 'B4'], ['E4', 'G4', 'C5']], ['F3', 'G3', 'C3'], ['IV', 'V', 'I']),
  ('plagal', L('Plagal cadence: IV - I ("Amen")', 'Plagalschluss: IV – I („Amen“)', 'Cadence plagale : IV – I (« Amen »)'),
   [['E4', 'G4', 'C5'], ['F4', 'A4', 'C5'], ['E4', 'G4', 'C5']], ['C3', 'F3', 'C3'], ['I', 'IV', 'I']),
  ('half', L('Half cadence: ends on V', 'Halbschluss: endet auf V', 'Demi-cadence : finit sur V'),
   [['E4', 'G4', 'C5'], ['F4', 'A4', 'C5'], ['D4', 'G4', 'B4']], ['C3', 'F3', 'G3'], ['I', 'IV', 'V']),
  ('deceptive', L('Deceptive (interrupted) cadence: V - vi', 'Trugschluss: V – vi', 'Cadence rompue (évitée) : V – vi'),
   [['E4', 'G4', 'C5'], ['D4', 'G4', 'B4'], ['C4', 'A4', 'C5']], ['C3', 'G3', 'A3'], ['I', 'V', 'vi']),
]
CADENCE_NAMES = {kind: name for kind, name, *_ in CADENCES}


def cadence_question(kind):
    _, name, rh, lh, labels = next(c for c in CADENCES if c[0] == kind)
    others = [c[1] for c in CADENCES if c[0] != kind]
    return ask(L('Which cadence is this?', 'Welcher Schluss ist das?', 'Quelle est cette cadence ?'), [name] + others, music=piano(rh, lh))


